-- ======== from cron jobs for consultations + ask-a-doctor expiry (pg_cron already exists on the original) ========
do $$ begin
  begin perform cron.unschedule('consultations-tick'); exception when others then null; end;
  perform cron.schedule('consultations-tick', '* * * * *', 'select public.consultations_tick()');
  begin perform cron.unschedule('consultations-summary-tick'); exception when others then null; end;
  perform cron.schedule('consultations-summary-tick', '* * * * *', 'select public.consultations_summary_tick()');
  begin perform cron.unschedule('ask-expire-tick'); exception when others then null; end;
  perform cron.schedule('ask-expire-tick', '*/15 * * * *', 'select public.ask_expire_tick()');
  begin perform cron.unschedule('stale-bookings-tick'); exception when others then null; end;
  perform cron.schedule('stale-bookings-tick', '*/10 * * * *', 'select public.stale_bookings_tick()');
  begin perform cron.unschedule('consultation-requests-tick'); exception when others then null; end;
  perform cron.schedule('consultation-requests-tick', '* * * * *', 'select public.consultation_requests_tick()');
end $$;

-- ======== from _guard_create_booking_offers.sql (security: re-apply after the v10 replace) ========
-- حماية create_booking_offers: بتحقن فحص "مين بينادي" في أي نسخة موجودة من الدالة (idempotent).
-- بتسمح: النظام (cron/trigger/service_role)، الأدمن، صاحب الحجز، أو حجز ضيف عمره أقل من 15 دقيقة.
do $guard$
declare
  v_def text;
  v_new text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_booking_offers'
   limit 1;
  if v_def is null or v_def like '%guard:caller%' then return; end if;

  v_new := regexp_replace(
    v_def,
    '(if\s+v_booking\s+is\s+null\s+or\s+v_booking\.provider_id\s+is\s+not\s+null\s+then\s+return;\s+end\s+if;)',
    E'\\1\n  -- guard:caller\n  if not (coalesce(auth.role(), ''service_role'') in (''service_role'', ''postgres'', ''supabase_admin'')\n          or public.is_admin()\n          or exists (select 1 from public.clients c where c.auth_id = auth.uid() and c.id = v_booking.client_id)\n          or (v_booking.client_id is null and v_booking.created_at > now() - interval ''15 minutes'')) then\n    return;\n  end if;',
    'i');
  if v_new not like '%guard:caller%' then
    raise exception 'create_booking_offers: مش لاقي مكان الحقن — راجع الدالة يدوي';
  end if;
  execute v_new;
end
$guard$;

commit;
